CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, subject TEXT NOT NULL, min_age INTEGER NOT NULL DEFAULT 4, max_age INTEGER NOT NULL DEFAULT 10, duration INTEGER NOT NULL DEFAULT 5, difficulty TEXT NOT NULL DEFAULT 'সহজ', thumbnail TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'quiz', entry_path TEXT, published INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS learners (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT 'আনিকা', age INTEGER NOT NULL DEFAULT 6, daily_goal INTEGER NOT NULL DEFAULT 15, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS game_assets (id TEXT PRIMARY KEY NOT NULL, game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE, path TEXT NOT NULL, content TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS game_asset_path_idx ON game_assets(game_id, path);
CREATE TABLE IF NOT EXISTS favorites (learner_id TEXT NOT NULL REFERENCES learners(id) ON DELETE CASCADE, game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE, PRIMARY KEY(learner_id, game_id));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY NOT NULL, learner_id TEXT NOT NULL REFERENCES learners(id) ON DELETE CASCADE, game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE, correct INTEGER NOT NULL, total INTEGER NOT NULL, stars INTEGER NOT NULL, duration INTEGER NOT NULL, completed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_learner_idx ON attempts(learner_id, completed_at);
